// Command embedconfig copies the repository's config/ into the module, so a
// binary run outside any checkout still has the shipped pack configs.
//
// The go:embed directive cannot reach ../config, so the copy lives at
// src/internal/defaultconfig/config/ and is regenerated by
//
//	make embed-config        # or: go -C src generate ./internal/defaultconfig
//
// defaultconfig's drift test fails whenever the copy and config/ differ, so a
// config change that forgets this step fails CI rather than shipping stale.
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"

	"github.com/ichava/icon-sets-sync/src/internal/defaultconfig"
)

func main() {
	root := flag.String("root", "..", "repository root, the directory holding config/ and src/")
	flag.Parse()
	n, err := defaultconfig.Sync(filepath.Join(*root, "config"), filepath.Join(*root, "src", "internal", "defaultconfig", "config"))
	if err != nil {
		fmt.Fprintln(os.Stderr, "embedconfig:", err)
		os.Exit(1)
	}
	fmt.Printf("embedconfig: %d files copied into src/internal/defaultconfig/config\n", n)
}
